#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${PULSAR_LOCAL_ROOT:-$PWD}"
PAYLOAD_SHA="919e0bb2389449a91a90d42bb7a638d0e94c6e42de136e22303c8689ba312e0f"
TMP="/tmp/pulsar-v8-two-glasses-${USER}-$$"
ARCHIVE="$TMP/payload.tar.gz"

cleanup() { rm -rf "$TMP"; }
trap cleanup EXIT

fail() {
  echo "ERROR: $*" >&2
  exit 1
}

[[ "$(hostname -s 2>/dev/null || hostname)" != "pulsar" ]] ||
  fail "این فایل را روی amin@localhost اجرا کن."

[[ -f "$ROOT/CMakeLists.txt" && -d "$ROOT/camera" &&
   -d "$ROOT/core" && -d "$ROOT/ui" ]] ||
  fail "از ریشه پروژه اجرا کن: cd ~/Music/Pulsar-Cpp-Core-PreStage8-Downloaded"

mkdir -p "$TMP"
cat <<'PAYLOAD_B64' | base64 -d >"$ARCHIVE"

PAYLOAD_B64

actual_sha="$(sha256sum "$ARCHIVE" | awk '{print $1}')"
[[ "$actual_sha" == "$PAYLOAD_SHA" ]] ||
  fail "هش Payload اشتباه است."

echo "============================================================"
echo "PULSAR V8 TWO INDEPENDENT GLASSES"
echo "Local project: $ROOT"
echo "Viewer profiles: monitor + two glasses"
echo "Monitor default: independent 2D"
echo "Glass defaults: independent 3D"
echo "Glass logical SBS: 3840x1080"
echo "Git operations: disabled"
echo "Persistent backup: disabled"
echo "============================================================"

echo
echo "[1/6] Installing the reviewed V8 files into the local project..."
rm -rf "$ROOT/ui/dist" "$ROOT/ui/frontend/dist"
tar -C "$ROOT" -xzf "$ARCHIVE"
chmod +x "$ROOT/run.sh" "$ROOT/core/scripts/"*.sh

echo
echo "[2/6] Validating every shell and the dynamic display layout..."
for shell in "$ROOT/run.sh" "$ROOT/core/scripts/"*.sh; do
  bash -n "$shell"
done

grep -q 'viewer-layout-ready=1 dynamic=1'   "$ROOT/camera/src/SbsRenderer.cpp"
grep -q 'live-layout-update=1'   "$ROOT/camera/src/SbsRenderer.cpp"
grep -q 'PULSAR_VIEWER_PANEL_SPECS'   "$ROOT/core/scripts/configure-displays.sh"
grep -q 'PULSAR_GLASS_LOGICAL_WIDTH=3840'   "$ROOT/core/config/pulsar.env"
grep -q 'std::array<std::string, 3> outputModes'   "$ROOT/core/include/pulsar/core/AppState.hpp"

if grep -Rqs --exclude='*.map'     -E 'ar-glass-3|PULSAR_ROLE_AR3|AR Glass 3'     "$ROOT/core/include" "$ROOT/core/scripts"     "$ROOT/ui/backend/src" "$ROOT/ui/frontend/src/app" "$ROOT/ui/dist"; then
  fail "پروفایل قدیمی عینک سوم هنوز در پروژه وجود دارد."
fi

echo
echo "[3/6] Verifying the locked image quality and fast pinned CUDA path..."
for profile in   "$ROOT/camera/profiles/FCU22080658-reference350-realtime.txt"   "$ROOT/camera/profiles/FCU22080659-reference350-realtime.txt"
do
  [[ -f "$profile" ]] || fail "پروفایل دوربین پیدا نشد: $profile"
  grep -q $'^DeviceLinkThroughputLimit\t350000000$' "$profile"
  grep -q $'^ExposureTime\t30000$' "$profile"
  grep -q $'^Gain\t0$' "$profile"
  grep -q $'^BlackLevel\t4$' "$profile"
  grep -q $'^StreamBufferHandlingMode\tNewestOnly$' "$profile"
done

grep -q 'cudaHostAllocWriteCombined'   "$ROOT/camera/src/GpuBayerPipeline.cu"
if grep -q 'PULSAR_GPU_DIRECT_SDK_H2D_V1'     "$ROOT/camera/src/GpuBayerPipeline.cu"; then
  fail "مسیر کند Direct SDK to CUDA هنوز فعال است."
fi

echo
echo "[4/6] Validating the compiled two-glasses UI..."
[[ -f "$ROOT/ui/dist/index.html" ]] ||
  fail "UI dist پیدا نشد."
[[ -n "$(find "$ROOT/ui/dist/assets" -maxdepth 1   -name 'index-*.js' -print -quit 2>/dev/null)" ]] ||
  fail "UI JavaScript build پیدا نشد."
if grep -Rqs 'AR Glass 3\|ar-glass-3' "$ROOT/ui/dist"; then
  fail "UI قدیمی سه‌عینکی هنوز Build شده است."
fi

echo "LOCAL_STATUS=V8_PATCHES_SAVED_IN_PROJECT"
echo "No Commit, Push, Tag or persistent backup was created."

if [[ "${PULSAR_PATCH_ONLY:-0}" == "1" ]]; then
  echo "PATCH_ONLY_STATUS=COMPLETE"
  exit 0
fi

echo
echo "[5/6] Uploading the exact latest local project and building CUDA on the server..."
cd "$ROOT"
./run.sh

echo
echo "[6/6] V8 installation and the automatic 20-second diagnosis finished."
echo "INSTALLER_STATUS=COMPLETE"
